INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch12$PT137-S4-Q25$batch12$, 137, 4, 25, $batch12$Parallel Flaw$batch12$, $batch12$Advertisement: The dental profession knows that brushing with Blizzard toothpaste is the best way to fight cavities. We surveyed five dentists, and each agreed that the tartar control formula found in Blizzard is the most effective cavity-fighting formula available in a toothpaste.$batch12$, $batch12$The flawed reasoning in which one of the following is most similar to the flawed reasoning in the advertisement?$batch12$, $batch12$D$batch12$, true, $batch12$Batch 12; question text from local bank.$batch12$ FROM lr_sections s WHERE s.preptest=137 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT137-S4-Q25$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$A$batch12$, $batch12$The nation's voters know that Gomez is the candidate whose policies would be best for the nation. Of ten voters polled, each said that Gomez would be a very popular leader.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT137-S4-Q25$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$A$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$B$batch12$, $batch12$Some of the nation's voters believe that Gomez is the candidate who would be best for the nation. Of the ten voters we surveyed, each agreed that the policies Gomez is committed to would be the best policies for the nation to adopt.$batch12$, $batch12$Bad Conclusion Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT137-S4-Q25$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$B$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$C$batch12$, $batch12$The nation's voters generally believe that Gomez is the candidate who would be best for the nation. We polled thousands of voters in the nation, and they agreed that the policies Gomez is committed to would help the nation more than those supported by any of the other candidates.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT137-S4-Q25$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$C$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$D$batch12$, $batch12$The nation's voters know that electing Gomez would be the best way to help the nation. The ten voters we polled all agreed that the policies Gomez is committed to would help the nation more than any other policies.$batch12$, $batch12$Correct$batch12$, true FROM lr_questions q WHERE q.qid=$batch12$PT137-S4-Q25$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$D$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$E$batch12$, $batch12$We know that electing Gomez would be the best course for the nation to follow because, of ten voters we surveyed, each agreed that electing Gomez would help the nation.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT137-S4-Q25$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$E$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT137-S4-Q25$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$The dental profession knows brushing with Blizzard is the best way to fight cavities.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Five dentists agreed Blizzard's tartar formula is the most effective cavity-fighting formula in a toothpaste.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Two flaws. Five dentists are treated as the whole profession. And agreement about one ingredient becomes a claim about the whole product being the best way to fight cavities.$batch12$), (3, $batch12$Goal$batch12$, $batch12$A tiny sample stands in for a whole group, and a claim about one part becomes a claim about the whole.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT137-S4-Q25$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$Being a popular leader isn't about policies. The evidence shifts to a different quality.$batch12$), ($batch12$B$batch12$, $batch12$"Some voters believe" is a modest conclusion that the ten voters do support.$batch12$), ($batch12$C$batch12$, $batch12$Thousands of voters is a large sample, so the first flaw disappears.$batch12$), ($batch12$D$batch12$, $batch12$Ten voters stand in for the nation's voters, and agreement about Gomez's policies becomes "electing Gomez is the best way." Both flaws match.$batch12$), ($batch12$E$batch12$, $batch12$"We know" isn't a claim about what voters know, and "would help" is weaker than "best."$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT137-S4-Q25$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
